import React, { useContext } from "react";
import { styled } from '@mui/material/styles';
import { UrlContext } from "./UrlContext";
import {
    Box,
    Table,
    TableBody,
    TableHead,
    TablePagination,
    TableRow,
    Paper,
    TableContainer,
    Skeleton,
    Stack,
    Typography,
} from "@mui/material";
import TableCell, { tableCellClasses } from '@mui/material/TableCell';
import UrlData from "./UrlData";

const StyledTableCell = styled(TableCell)(({ theme }) => ({
    [`&.${tableCellClasses.head}`]: {
        backgroundColor: theme.palette.common.black,
        color: theme.palette.common.white,
    },
    [`&.${tableCellClasses.body}`]: {
        fontSize: 14,
    },
}));

const UrlList = () => {
    const urlConsumer = useContext(UrlContext);

    return (
        <Paper elevation={1}>
            <TableContainer component={Paper} sx={{ mt: 3, borderRadius: 2, boxShadow: '0 8px 24px rgba(0, 0, 0, 0.1)' }}>
                <Box display="flex" justifyContent="end" padding={2}>
                    <TablePagination
                        color="primary"
                        count={urlConsumer.totalCount}
                        rowsPerPageOptions={[5, 10, 25]}
                        rowsPerPage={parseInt(sessionStorage.getItem("limit"), 10)}
                        page={parseInt(sessionStorage.getItem("page"), 10)}
                        onPageChange={urlConsumer.handlePageChange}
                        onRowsPerPageChange={urlConsumer.handleRowPerPageChange}
                    />
                </Box>
                {urlConsumer.loading ? (
                    <Stack spacing={1} sx={{ p: 2 }}>
                        <Skeleton animation="wave" variant="rounded" width={420} />
                        <Skeleton animation="wave" variant="rounded" width={420} />
                        <Skeleton animation="wave" variant="rounded" width={420} />
                        <Skeleton animation="wave" variant="rounded" />
                        <Skeleton animation="wave" variant="rounded" />
                        <Skeleton animation="wave" variant="rounded" />
                    </Stack>
                ) : urlConsumer.emptyList ? (
                    <Box sx={{ p: 4, textAlign: 'center' }}>
                        <Typography color="text.secondary">No URLs yet — add one to get started.</Typography>
                    </Box>
                ) : (
                    <Table sx={{ minWidth: 650 }} aria-label="simple table">
                        <TableHead>
                            <TableRow>
                                <StyledTableCell>Sr. No</StyledTableCell>
                                <StyledTableCell>Short URL</StyledTableCell>
                                <StyledTableCell>Description</StyledTableCell>
                                <StyledTableCell>Count</StyledTableCell>
                                <StyledTableCell>Expiration Date</StyledTableCell>
                                <StyledTableCell>Actions</StyledTableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {urlConsumer.list.map((url, index) => (
                                <UrlData
                                    key={url._id}
                                    urlData={url}
                                    index={index + 1}
                                />
                            ))}
                        </TableBody>
                    </Table>
                )}
            </TableContainer>
        </Paper>
    );
};

export default UrlList;
