import React, { useState } from "react";
import {
  Box,
  IconButton,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";
import { useTheme } from "@mui/material/styles";
import PictureAsPdfIcon from "@mui/icons-material/PictureAsPdf";
import ImageIcon from "@mui/icons-material/Image";
import AudiotrackIcon from "@mui/icons-material/Audiotrack";
import VideoLibraryIcon from "@mui/icons-material/VideoLibrary";
import InsertDriveFileIcon from "@mui/icons-material/InsertDriveFile";

const MediaPreview = ({ file, originalUrl }) => {
  const theme = useTheme();
  const isDarkMode = theme.palette.mode === "dark";
  const [open, setOpen] = useState(false);

  const handleFileClick = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const getThumbnail = (type) => {
    switch (type) {
      case "image":
        return <ImageIcon fontSize="large" />;
      case "pdf":
        return <PictureAsPdfIcon fontSize="large" />;
      case "audio":
        return <AudiotrackIcon fontSize="large" />;
      case "video":
        return <VideoLibraryIcon fontSize="large" />;
      default:
        return <InsertDriveFileIcon fontSize="large" />;
    }
  };

  const getFileType = (file) => {
    if (["jpg", "jpeg", "png", "bmp"].includes(file.format)) return "image";
    if (["mp3", "aac"].includes(file.format)) return "audio";
    if (file.format === "pdf") return "pdf";
    if (file.format === "mp4") return "video";
    return "other";
  };

  const renderMediaContent = (type) => {
    const fileUrl = originalUrl;
    switch (type) {
      case "image":
        return (
          <img
            src={fileUrl}
            alt="preview"
            style={{ width: "100%", height: "auto" }}
          />
        );
      case "pdf":
        return (
          <iframe
            src={fileUrl}
            title="PDF Preview"
            style={{ width: "100%", height: "500px" }}
          />
        );
      case "audio":
        return <audio controls src={fileUrl} style={{ width: "100%" }} />;
      case "video":
        return (
          <video
            controls
            src={fileUrl}
            style={{
              width: '100%',
              height: 'auto',
              maxHeight: '500px', // Prevents the video from being too tall
              objectFit: 'contain', // Ensures the video retains aspect ratio
            }}
          />
        )
      default:
        return <Typography>Unsupported file type.</Typography>;
    }
  };

  return (
    <>
      {/* Thumbnail for the file */}
      <Box
        sx={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          border: "1px solid #ccc",
          marginTop: 2, 
          padding: 2,
          borderRadius: 2,
          cursor: "pointer",
          width: 120,
          textAlign: "center",
          backgroundColor: isDarkMode ? "#333" : "#f9f9f9",
          color: isDarkMode ? '#fff' : '#000',
          "&:hover": {
            backgroundColor: isDarkMode ? "#444" : "#f1f1f1",
          },
        }}
        onClick={handleFileClick}
      >
        <IconButton>{getThumbnail(getFileType(file))}</IconButton>
        <Typography variant="body2" sx={{ marginTop: 1 }}>
          Click to open
        </Typography>
      </Box>

      {/* Modal/Dialog for file preview */}
      <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
        <DialogTitle>File Preview</DialogTitle>
        <DialogContent dividers>
          {renderMediaContent(getFileType(file))}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose} color="primary">
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default MediaPreview;
