// src/components/CreateUrl.js
import React, { useEffect, useState } from 'react';
import { Box, TextField, Button, Container, Typography, FormGroup, Fade, CircularProgress, Tooltip } from '@mui/material';
import { useNavigate, useParams } from 'react-router-dom';
import { QRCodeSVG } from 'qrcode.react';
import { AdapterMoment } from '@mui/x-date-pickers/AdapterMoment';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { renderTimeViewClock } from '@mui/x-date-pickers/timeViewRenderers';
import { isLoggedIn } from '../utils/GenUtils';
import UrlApi from '../data/UrlApi';
import AlertBox from './Alert/AlertBox';
import moment from 'moment';
import AlertSnackbar from './Alert/Snackbar';
import MediaPreview from './Alert/MediaPreview';

const getDefaultErrorState = () => ({
    main: false,
    originalUrl: false,
    urlName: false,
    expirationDate: false,
    OU_helperText: "",
    UN_helperText: "",
    ED_helperText: ""
});

function CreateUrl(props) {
    const [originalUrl, setOriginalUrl] = useState('');
    const [expirationDate, setExpirationDate] = useState(moment());
    const [urlName, setUrlName] = useState('');
    const [file, setFile] = useState({});
    const [error, setError] = useState(getDefaultErrorState());
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [pageLoader, setPageLoader] = useState(false);
    const [snackbarOpen, setSnackbarOpen] = useState(false);
    const [snackbarMessage, setSnackbarMessage] = useState("");
    const [fade, setFade] = useState(true);
    const navigate = useNavigate();
    const params = useParams();

    useEffect(() => {
        if (props.mode === 'update') {
            viewUrlDetails();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [props.mode]);

    const handleClickOpen = () => {
        if (props.mode === 'add') {
            if (originalUrl || urlName) {
                setOpen(true);
            } else {
                navigate("/");
            }
        } else {
            navigate("/");
        }
    };

    const handleClose = () => {
        setOpen(false);
    };

    const handleConfirm = () => {
        setFade(false);
        setOpen(false);
        setTimeout(() => {
            setOriginalUrl("");
            setUrlName("");
            setError(getDefaultErrorState());
            navigate("/");
        }, 500);
    };

    const handleChange = (e, error = '', type) => {
        if (type === 'expirationDate') {
            setExpirationDate(moment(e));
            setError(prevState => ({ ...prevState, expirationDate: false, ED_helperText: "" }));
        } else if (e.target.name === 'originalUrl') {
            setOriginalUrl(e.target.value);
            setError(prevState => ({ ...prevState, originalUrl: false, OU_helperText: "" }));
        } else if (e.target.name === 'urlName') {
            setUrlName(e.target.value);
            setError(prevState => ({ ...prevState, urlName: false, UN_helperText: "" }));
        }
    };

    const viewUrlDetails = () => {
        setPageLoader(true);
        if (!navigator.onLine) {
            setSnackbarMessage("Offline: Not connected");
            setSnackbarOpen(true);
            setPageLoader(false);
            return;
        }

        if (!isLoggedIn()) {
            setSnackbarMessage("Invalid session, please login again.");
            setSnackbarOpen(true);
            setPageLoader(false);
            return;
        }

        UrlApi.getUrlDetails(params.urlId, (err, res) => {
            setPageLoader(false);
            if (err) {
                const message = err?.data?.message || "Unable to load this URL's details";
                if (err?.data?.status === 401) {
                    navigate("/login");
                }
                setSnackbarMessage(message);
                setSnackbarOpen(true);
                return;
            }
            if (res.data?.code === 200) {
                const urlData = res.data.data;
                if (urlData.file?.length) {
                    setFile(urlData.file[0]);
                }
                setUrlName(urlData.urlName);
                setOriginalUrl(urlData.originalUrl);
                setExpirationDate(moment(urlData.expirationDate));
            }
        });
    };

    const handleSnackbarClose = () => {
        setSnackbarOpen(false);
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setLoading(true);
        if (!originalUrl || !expirationDate || !urlName) {
            if (!originalUrl) {
                setError(prevState => ({ ...prevState, originalUrl: true, OU_helperText: "This is required field" }));
            }
            if (!expirationDate) {
                setError(prevState => ({ ...prevState, expirationDate: true, ED_helperText: "This is required field" }));
            }
            if (!urlName) {
                setError(prevState => ({ ...prevState, urlName: true, UN_helperText: "This is required field" }));
            }
            setLoading(false);
            setSnackbarMessage("All fields are required!");
            setSnackbarOpen(true);
            return;
        }

        let reqObj = {};
        if (props.mode === "add") {
            reqObj = { originalUrl, urlName, expirationDate };
        } else {
            reqObj["urlId"] = params.urlId;
            if (urlName) reqObj["urlName"] = urlName;
            if (expirationDate) reqObj["expirationDate"] = expirationDate;
        }

        const apiCall = props.mode === "add" ? UrlApi.addUrl : UrlApi.updateUrl;

        apiCall(reqObj, (err, res) => {
            setLoading(false);
            if (err) {
                const message = err?.data?.error ? err.data.error[0].message : (err?.data?.message || "Something went wrong");
                if (err?.data?.status === 401) {
                    navigate("/login");
                }
                setSnackbarMessage(message);
                setSnackbarOpen(true);
                return;
            }
            setSnackbarMessage(res.data.message);
            setSnackbarOpen(true);
            setOriginalUrl("");
            setUrlName("");
            setExpirationDate(moment());
            sessionStorage.setItem("page", 0);
            navigate("/");
        });
    };

    return (
        <Fade in={fade} timeout={500}>
            <Container sx={{ marginTop: 4 }}>
                <AlertSnackbar
                    snackbarOpen={snackbarOpen}
                    snackbarMessage={snackbarMessage}
                    handleSnackbarClose={handleSnackbarClose}
                />
                {pageLoader ? (
                    <Box
                        sx={{
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                            height: '100vh',
                            width: '100vw',
                            position: 'fixed',
                            backgroundColor: 'rgba(0, 0, 0, 0.1)',
                            zIndex: 9999,
                            top: 0,
                            left: 0,
                        }}
                    >
                        <CircularProgress />
                    </Box>
                ) : (
                    <React.Fragment>
                        <Typography variant="h5">{props.mode === "add" ? "Create" : "Update"} Short URL</Typography>
                        <FormGroup>
                            {props.mode === "update" ? (
                                <Tooltip title="Unable to update original url. Please create a new one" arrow>
                                    <TextField
                                        label="Original URL"
                                        fullWidth
                                        margin="normal"
                                        value={originalUrl}
                                        name="originalUrl"
                                        error={error.originalUrl}
                                        helperText={error.OU_helperText}
                                        type="url"
                                        placeholder="Enter a valid url starting with http or https"
                                        onChange={handleChange}
                                        disabled={true}
                                    />
                                </Tooltip>
                            ) : (
                                <TextField
                                    label="Original URL"
                                    fullWidth
                                    margin="normal"
                                    value={originalUrl}
                                    name="originalUrl"
                                    error={error.originalUrl}
                                    helperText={error.OU_helperText}
                                    type="url"
                                    placeholder="Enter a valid url starting with http or https"
                                    onChange={handleChange}
                                />
                            )}
                            <TextField
                                label="URL Name"
                                fullWidth
                                margin="normal"
                                name="urlName"
                                placeholder="Description of the URL"
                                error={error.urlName}
                                helperText={error.UN_helperText}
                                value={urlName}
                                onChange={handleChange}
                            />
                            <LocalizationProvider dateAdapter={AdapterMoment}>
                                <DateTimePicker
                                    label="Expiration Date"
                                    name="expirationDate"
                                    format="DD/MM/YYYY hh:mm a"
                                    showDaysOutsideCurrentMonth={true}
                                    value={expirationDate}
                                    slotProps={{
                                        textField: {
                                            fullWidth: true,
                                            margin: "normal",
                                            error: error.expirationDate,
                                            helperText: error.ED_helperText
                                        },
                                        actionBar: {
                                            actions: ["cancel"],
                                        },
                                    }}
                                    onChange={(value, error) => handleChange(value, error, "expirationDate")}
                                    viewRenderers={{
                                        hours: renderTimeViewClock,
                                        minutes: renderTimeViewClock,
                                        seconds: renderTimeViewClock,
                                    }}
                                />
                            </LocalizationProvider>

                            {Object.keys(file).length > 0 && <MediaPreview file={file} originalUrl={originalUrl} />}

                            <Box sx={{ marginTop: 3, display: 'flex', justifyContent: 'flex-end', gap: 3 }}>
                                <Button onClick={handleSubmit} variant='contained' color="primary" disabled={loading}>
                                    {loading ? <CircularProgress size={24} /> : (props.mode === "update" ? 'Update' : 'Create')}
                                </Button>
                                <Button onClick={handleClickOpen} variant='outlined' color="primary" disabled={loading}>
                                    Cancel
                                </Button>
                            </Box>
                        </FormGroup>
                    </React.Fragment>
                )}
                <AlertBox
                    open={open}
                    handleClose={handleClose}
                    handleConfirm={handleConfirm}
                    modalContent="Are you sure you want to go back? Your changes will not be saved."
                />
            </Container>
        </Fade>
    );
}

export default CreateUrl;
