import React, { useCallback, useEffect } from "react";
import {
  BrowserRouter,
  Route,
  Routes,
} from "react-router-dom";
import { ThemeProvider } from "@mui/material/styles";
import { CssBaseline } from '@mui/material'
import { UrlProvider } from "./components/UrlContext";
import About from "./components/About";
import Login from "./components/Login";
import CreateUrl from "./components/NEW_AddUrl";
import UrlPage1 from "./components/UrlPage";
import Navbar from "./NavBar/Navbar";
import FileUploadPage from "./components/Upload";
import ProtectedRoute from "./components/routes/ProtectedRoute";
import NotFoundPage from "./components/routes/NotFoundPage";
import { getAppTheme } from "./theme";

const App = () => {
    const storedMode = sessionStorage.getItem("isDarkMode");
    const initialDarkMode = storedMode === "dark";
    const [darkMode, setDarkMode] = React.useState(initialDarkMode);
    const [login, setLogin] = React.useState(false);

  useEffect(() => {
    sessionStorage.setItem("isDarkMode", darkMode ? "dark" : "light")
  }, [darkMode])

  const handleDarkModeToggle = () => {
    setDarkMode(prevMode => !prevMode);
  };

  const useLoginCallback = useCallback((value) => setLogin(value), []);

    // useMemo so the theme object isn't rebuilt on every render
    const theme = React.useMemo(() => getAppTheme(darkMode ? "dark" : "light"), [darkMode]);
  return (
    <UrlProvider>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <BrowserRouter>
          <Navbar
            darkMode={darkMode}
            toggleDarkMode={handleDarkModeToggle}
            login={login}
          />
          <Routes>
            <Route path="/login" element={<Login setLogin={useLoginCallback} />} />
            {/* <Route path="/url/upload" element={< FileUploadWithPreview />} /> */}
            <Route path="/about" element={<About />} />
            {/* <Route path="/red/:customUrl" element={<RedirectPage />} /> */}
            <Route element={<ProtectedRoute />} >
              <Route path="/" element={<UrlPage1 />} />
              <Route path="/url/add" element={<CreateUrl mode="add" />} />
              <Route path="/url/:urlId" element={<CreateUrl mode="update" />} />
              <Route path="/url/upload" element={<FileUploadPage />} />
            </Route>
            <Route path="*" element={<NotFoundPage />} />
          </Routes>
        </BrowserRouter>
      </ThemeProvider>
    </UrlProvider>
  );
};

export default App;
