import React, { useState } from "react";
import { Box, Button, Divider, Grid2 as Grid, Paper, Typography, TextField, CircularProgress } from "@mui/material";
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { renderTimeViewClock } from '@mui/x-date-pickers/timeViewRenderers';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import moment from "moment";
import { UPLOAD_BULK_CSV_ROUTE, UPLOAD_FILE_ROUTE } from "../config/routeConfig";
import { getToken } from "../utils/GenUtils";
import { ToastContainer, toast } from "react-toastify";
import axios from "axios";
import { AdapterMoment } from "@mui/x-date-pickers/AdapterMoment";
import { useNavigate } from "react-router-dom";
import { MAX_FILE_SIZE_LIMIT } from "../constants/Constant";

export default function FileUploadPage() {
    const [file, setFile] = useState(null);
    const [urlName, setUrlName] = useState("");
    const [expirationDate, setExpirationDate] = useState(moment());
    const [csvFile, setCsvFile] = useState(null);
    const [fileLoading, setFileLoading] = useState(false);
    const [csvLoading, setCsvLoading] = useState(false);
    const [shortUrl, setShortUrl] = useState(null);
    const navigate = useNavigate();

    const handleChange = (e, error = '', type) => {
        if (type === 'expirationDate') {
            setExpirationDate(moment(e));
        } else if (e.target.name === 'urlName') {
            setUrlName(e.target.value);
        }
    };

    const handleFileUpload = async (e) => {
        e.preventDefault();
        setFileLoading(true);
        if (file.size >= MAX_FILE_SIZE_LIMIT) {
            toast("File size must not exceed 5 MB.", { autoClose: 1500 });
            setFileLoading(false);
            return;
        }
        const formData = new FormData();
        formData.append("file", file);
        formData.append("expirationDate", expirationDate);
        formData.append("urlName", urlName);
        axios({
            url: UPLOAD_FILE_ROUTE,
            method: "post",
            headers: { Authorization: getToken() },
            data: formData
        })
            .then(res => {
                if (res.data?.code === 200) {
                    const { data } = res;
                    toast(data.message, { autoClose: 1500 });
                    setShortUrl(data.data.url);
                    setFileLoading(false);
                    setFile(null);
                    setUrlName("");
                    setExpirationDate(null);
                }
            })
            .catch(err => {
                setFileLoading(false);
                const data = err?.response?.data;
                if (data?.status === 401) {
                    navigate("/login");
                }
                const message = data?.error ? data.error[0].message : (data?.message || "Upload failed");
                toast(message, { autoClose: 1500 });
            });
    };

    const handleCsvUpload = async (e) => {
        e.preventDefault();
        setCsvLoading(true);
        const formData = new FormData();
        formData.append("file", csvFile);
        axios({
            url: UPLOAD_BULK_CSV_ROUTE,
            method: "post",
            headers: { Authorization: getToken() },
            data: formData
        })
            .then(res => {
                if (res.data?.code === 200) {
                    const { data } = res;
                    toast(data.message, { autoClose: 1500 });
                    setCsvLoading(false);
                    setCsvFile(null);
                }
            })
            .catch(err => {
                setCsvLoading(false);
                const data = err?.response?.data;
                if (data?.status === 401) {
                    navigate("/login");
                }
                const message = data?.error ? data.error[0].message : (data?.message || "Upload failed");
                toast(message, { autoClose: 1500 });
            });
    };

    const handleBack = () => {
        navigate("/");
    };

    return (
        <Box sx={{ maxWidth: 800, margin: "auto", mt: 4 }}>
            <ToastContainer />
            <Paper elevation={3} sx={{ p: 4 }}>
                <Button variant="outlined" startIcon={<ArrowBackIcon />} onClick={handleBack} sx={{ mb: 2 }}>
                    Back
                </Button>
                <Typography variant="h4" gutterBottom>
                    File Upload Dashboard
                </Typography>

                <Box component="form" onSubmit={handleFileUpload}>
                    <Typography variant="h6">Upload Any File (PDF, Image, Video)</Typography>
                    <TextField
                        fullWidth
                        type="file"
                        slotProps={{
                            htmlInput: { accept: "image/*,application/pdf,video/*,audio/*" }
                        }}
                        onChange={(e) => setFile(e.target.files[0])}
                        sx={{ mt: 2 }}
                    />
                    <TextField
                        fullWidth
                        label="URL Name"
                        name="urlName"
                        value={urlName}
                        onChange={handleChange}
                        required
                        sx={{ mt: 2 }}
                        slotProps={{ htmlInput: { "aria-label": "urlName" } }}
                    />
                    <LocalizationProvider dateAdapter={AdapterMoment}>
                        <DateTimePicker
                            label="Expiration Date"
                            name="expirationDate"
                            format="DD/MM/YYYY hh:mm a"
                            showDaysOutsideCurrentMonth={true}
                            value={expirationDate}
                            sx={{ mt: 2 }}
                            slotProps={{
                                textField: { fullWidth: true, margin: "normal" },
                                actionBar: { actions: ["cancel"] },
                            }}
                            onChange={(value, error) => handleChange(value, error, "expirationDate")}
                            viewRenderers={{
                                hours: renderTimeViewClock,
                                minutes: renderTimeViewClock,
                                seconds: renderTimeViewClock,
                            }}
                        />
                    </LocalizationProvider>
                    <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        startIcon={<CloudUploadIcon />}
                        disabled={fileLoading || !file}
                        sx={{ mt: 2 }}
                    >
                        {fileLoading ? <CircularProgress size={24} /> : "Upload File"}
                    </Button>
                    {shortUrl && (
                        <Typography variant="body1" sx={{ mt: 2 }}>
                            Short URL: <a href={shortUrl} target="_blank" rel="noopener noreferrer">{shortUrl}</a>
                        </Typography>
                    )}
                </Box>

                <Divider sx={{ my: 4 }} />

                <Box component="form" onSubmit={handleCsvUpload}>
                    <Typography variant="h6">Upload CSV File with URLs</Typography>
                    <TextField
                        fullWidth
                        type="file"
                        slotProps={{ htmlInput: { accept: ".csv" } }}
                        onChange={(e) => setCsvFile(e.target.files[0])}
                        sx={{ mt: 2, mb: 2 }}
                    />
                    <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        startIcon={<CloudUploadIcon />}
                        disabled={csvLoading || !csvFile}
                    >
                        {csvLoading ? <CircularProgress size={24} /> : "Upload CSV"}
                    </Button>
                </Box>
            </Paper>
        </Box>
    );
}
