import axios from "axios";
import {
    LOGIN_ROUTE,
    LOGOUT_ROUTE,
    LIST_URL_ROUTE,
    INSERT_URL_ROUTE,
    UPDATE_URL_ROUTE,
    DELETE_UPDATE_URL_ROUTE
} from '../config/routeConfig';
import { getToken } from '../utils/GenUtils';

export default class UrlApi {

    static addUrl(data, callback) {
        axios.post(INSERT_URL_ROUTE, { ...data }, {
            headers: { 'Authorization': getToken() }
        })
            .then(res => callback(null, res))
            .catch(err => callback(err, null));
    }

    static updateUrl(data, callback) {
        axios.patch(UPDATE_URL_ROUTE, { ...data }, {
            headers: { 'Authorization': getToken() }
        })
            .then(res => callback(null, res))
            .catch(err => callback(err, null));
    }

    static deleteUrl(id, callback) {
        axios.delete(`${DELETE_UPDATE_URL_ROUTE}/${id}`, {
            headers: { 'Authorization': getToken() }
        })
            .then(res => callback(null, res))
            .catch(err => callback(err, null));
    }

    static getUrlDetails(urlId, callback) {
        axios.get(`${DELETE_UPDATE_URL_ROUTE}/${urlId}`, {
            headers: { 'Authorization': getToken() }
        })
            .then(res => callback(null, res))
            .catch(err => callback(err, null));
    }

    static login(data, callback) {
        axios.post(LOGIN_ROUTE, { ...data })
            .then(res => callback(null, res.data))
            .catch(err => callback(err.response, null));
    }

    static logout(callback) {
        axios.get(LOGOUT_ROUTE, {
            headers: { 'Authorization': getToken() }
        })
            .then(res => callback(null, res.data))
            .catch(err => callback(err.response, null));
    }

    static listUrl(data, callback) {
        axios.post(LIST_URL_ROUTE, { ...data }, {
            headers: { 'Authorization': getToken() }
        })
            .then(res => callback(res))
            .catch(err => callback(err));
    }
}
