import { createTheme } from '@mui/material/styles';

// Shared design tokens that don't change between light/dark
const shape = {
    borderRadius: 10,
};

const typography = {
    fontFamily: '"Inter", "Roboto", "Helvetica", "Arial", sans-serif',
    h4: { fontWeight: 700, letterSpacing: '-0.01em' },
    h5: { fontWeight: 600 },
    h6: { fontWeight: 600 },
    button: {
        fontWeight: 600,
        textTransform: 'none', // stock MUI's ALL-CAPS buttons are the #1 "looks like a tutorial" tell
    },
};

const getDesignTokens = (mode) => ({
    palette: {
        mode,
        primary: {
            main: mode === 'dark' ? '#7dd3fc' : '#0f62d6',
            contrastText: '#ffffff',
        },
        secondary: {
            main: mode === 'dark' ? '#f9a8d4' : '#d6336c',
        },
        background: {
            default: mode === 'dark' ? '#0f1115' : '#f6f7fb',
            paper: mode === 'dark' ? '#171a21' : '#ffffff',
        },
        divider: mode === 'dark' ? 'rgba(255,255,255,0.08)' : 'rgba(15,23,42,0.08)',
    },
    shape,
    typography,
    components: {
        MuiAppBar: {
            styleOverrides: {
                root: ({ theme }) => ({
                    backgroundColor: theme.palette.mode === 'dark' ? '#12141a' : '#ffffff',
                    color: theme.palette.mode === 'dark' ? '#fff' : '#0f1115',
                    boxShadow: '0 1px 0 rgba(0,0,0,0.06)',
                }),
            },
        },
        MuiButton: {
            styleOverrides: {
                root: {
                    borderRadius: 8,
                    paddingInline: 18,
                    paddingBlock: 8,
                },
                contained: {
                    boxShadow: 'none',
                    '&:hover': { boxShadow: '0 4px 12px rgba(15,98,214,0.25)' },
                },
            },
        },
        MuiPaper: {
            styleOverrides: {
                root: {
                    backgroundImage: 'none', // kills MUI's default dark-mode overlay gradient banding
                },
            },
        },
        MuiTableCell: {
            styleOverrides: {
                head: ({ theme }) => ({
                    backgroundColor: theme.palette.mode === 'dark' ? '#1c1f27' : '#f1f3f9',
                    color: theme.palette.text.primary,
                    fontWeight: 600,
                    fontSize: 13,
                    textTransform: 'uppercase',
                    letterSpacing: '0.04em',
                }),
                body: {
                    fontSize: 14,
                },
            },
        },
        MuiTableRow: {
            styleOverrides: {
                root: ({ theme }) => ({
                    '&:hover': {
                        backgroundColor: theme.palette.mode === 'dark'
                            ? 'rgba(255,255,255,0.03)'
                            : 'rgba(15,98,214,0.03)',
                    },
                }),
            },
        },
        MuiChip: {
            styleOverrides: {
                root: { fontWeight: 600 },
            },
        },
        MuiTextField: {
            defaultProps: {
                variant: 'outlined',
            },
        },
        MuiTableContainer: {
            styleOverrides: {
                root: ({ theme }) => ({
                    border: `1px solid ${theme.palette.divider}`,
                }),
            },
        },
    },
});

// Exported factory — pass 'light' or 'dark'
export const getAppTheme = (mode) => createTheme(getDesignTokens(mode));

// Default export kept for any existing static import (light mode)
export default getAppTheme('light');
